import{_ as i,a0 as r,w as l,s,ao as c,I as a,x as t,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Linux 中用 nmcli 命令綁定多塊網卡 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中用 nmcli 命令綁定多塊網卡 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中用 nmcli 命令綁定多塊網卡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中用 nmcli 命令綁定多塊網卡 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150108 Interface (NICs) Bonding in Linux using nmcli","title":"在 Linux 中用 nmcli 命令綁定多塊網卡","tag":"201505","desc":""},"relativePath":"201505/20150108 Interface (NICs) Bonding in Linux using nmcli.md","filePath":"[post].md"}'),m={name:"201505/20150108 Interface (NICs) Bonding in Linux using nmcli.md"};function d(g,n,u,x,h,f){const e=r("Link");return l(),s("div",null,[n[13]||(n[13]=c(`<h1 id="在-linux-中用-nmcli-命令綁定多塊網卡" tabindex="-1">在 Linux 中用 nmcli 命令綁定多塊網卡 <a class="header-anchor" href="#在-linux-中用-nmcli-命令綁定多塊網卡" aria-label="Permalink to “在 Linux 中用 nmcli 命令綁定多塊網卡”">​</a></h1><p>今天，我們來學習一下在 CentOS 7.x 中如何用 nmcli（Network Manager Command Line Interface：網絡管理命令列接口）進行網卡綁定。</p><p>網卡（接口）綁定是將多塊 <strong>網卡</strong> 邏輯地連接到一起從而允許故障轉移或者提高吞吐率的方法。提高服務器網絡可用性的一個方式是使用多個網卡。Linux 綁定驅動程序提供了一種將多個網卡聚合到一個邏輯的綁定接口的方法。這是個新的實現綁定的方法，並不影響 linux 內核中舊綁定驅動。</p><p><strong>網卡綁定為我們提供了兩個主要的好處:</strong></p><ol><li><strong>高帶寬</strong></li><li><strong>冗餘/彈性</strong></li></ol><p>現在讓我們在 CentOS 7 上配置網卡綁定吧。我們需要決定選取哪些接口配置成一個組接口（Team interface）。</p><p>運行 <strong>ip link</strong> 命令查看系統中可用的接口。</p><pre><code> $ ip link
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/ip-link.png" alt="ip link"></p><p>這裏我們使用 <strong>eno16777736</strong> 和 <strong>eno33554960</strong> 網卡在 “主動備份” 模式下創建一個組接口。(譯者注：關於不同模式可以參考：<a href="http://support.huawei.com/ecommunity/bbs/10155553.html">多網卡的7種bond模式原理</a>)</p><p>按照下面的語法，用 <strong>nmcli</strong> 命令為網絡組接口創建一個連接。</p><pre><code># nmcli con add type team con-name CNAME ifname INAME [config JSON]
</code></pre><p><strong>CNAME</strong> 指代連接的名稱，<strong>INAME</strong> 是接口名稱，<strong>JSON</strong> (JavaScript Object Notation) 指定所使用的處理器(runner)。<strong>JSON</strong> 語法格式如下：</p><pre><code>&#39;{&quot;runner&quot;:{&quot;name&quot;:&quot;METHOD&quot;}}&#39; 
</code></pre><p><strong>METHOD</strong> 是以下的其中一個：<strong>broadcast、activebackup、roundrobin、loadbalance</strong> 或者 <strong>lacp</strong>。</p><h3 id="_1-創建組接口" tabindex="-1">1. 創建組接口 <a class="header-anchor" href="#_1-創建組接口" aria-label="Permalink to “1. 創建組接口”">​</a></h3><p>現在讓我們來創建組接口。這是我們創建組接口所使用的命令。</p><pre><code> # nmcli con add type team con-name team0 ifname team0 config &#39;{&quot;runner&quot;:{&quot;name&quot;:&quot;activebackup&quot;}}&#39;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nmcli-con-create.png" alt="nmcli con create"></p><p>運行 <strong># nmcli con show</strong> 命令驗證組接口配置。</p><pre><code># nmcli con show
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/show-team-interface.png" alt="顯示組接口"></p><h3 id="_2-添加從設備" tabindex="-1">2. 添加從設備 <a class="header-anchor" href="#_2-添加從設備" aria-label="Permalink to “2. 添加從設備”">​</a></h3><p>現在讓我們添加從設備到主設備 team0。這是添加從設備的語法：</p><pre><code># nmcli con add type team-slave con-name CNAME ifname INAME master TEAM
</code></pre><p>在這裏我們添加 <strong>eno16777736</strong> 和 <strong>eno33554960</strong> 作為 <strong>team0</strong> 接口的從設備。</p><pre><code># nmcli con add type team-slave con-name team0-port1 ifname eno16777736 master team0

# nmcli con add type team-slave con-name team0-port2 ifname eno33554960 master team0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/adding-to-team.png" alt="添加從設備到 team"></p><p>再次用命令 <strong>#nmcli con show</strong> 驗證連接配置。現在我們可以看到從設備配置信息。</p><pre><code>#nmcli con show
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/show-slave-config.png" alt="顯示從設備配置"></p><h3 id="_3-分配-ip-地址" tabindex="-1">3. 分配 IP 地址 <a class="header-anchor" href="#_3-分配-ip-地址" aria-label="Permalink to “3. 分配 IP 地址”">​</a></h3><p>上面的命令會在 <strong>/etc/sysconfig/network-scripts/</strong> 目錄下創建需要的配置文件。</p><p>現在讓我們為 team0 接口分配一個 IP 地址並啓用這個連接。這是進行 IP 分配的命令。</p><pre><code># nmcli con mod team0 ipv4.addresses &quot;192.168.1.24/24 192.168.1.1&quot;
# nmcli con mod team0 ipv4.method manual
# nmcli con up team0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/ip-assignment.png" alt="分配 ip"></p><h3 id="_4-驗證綁定" tabindex="-1">4. 驗證綁定 <a class="header-anchor" href="#_4-驗證綁定" aria-label="Permalink to “4. 驗證綁定”">​</a></h3><p>用 <strong>#ip add show team0</strong> 命令驗證 IP 地址信息。</p><pre><code>#ip add show team0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/verfiy-ip-adress.png" alt="驗證 ip 地址"></p><p>現在用 <strong>teamdctl</strong> 命令檢查 <strong>主動備份</strong> 配置功能。</p><pre><code># teamdctl team0 state
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/teamdctl-activebackup-check.png" alt="teamdctl 檢查主動備份"></p><p>現在讓我們把激活的端口斷開連接並再次檢查狀態來確認主動備份配置是否像希望的那樣工作。</p><pre><code># nmcli dev dis eno33554960
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/disconnect-activeport.png" alt="斷開激活端口連接"></p><p>斷開激活端口後再次用命令 <strong>#teamdctl team0 state</strong> 檢查狀態。</p><pre><code># teamdctl team0 state
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/teamdctl-check-activeport-disconnect.png" alt="teamdctl 檢查斷開激活端口連接"></p><p>是的，它運行良好！！我們會使用下面的命令連接回到 team0 的斷開的連接。</p><pre><code>#nmcli dev con eno33554960
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/nmcli-dev-connect-disconected.png" alt="nmcli dev 連接斷開的連接"></p><p>我們還有一個 <strong>teamnl</strong> 命令可以顯示 <strong>teamnl</strong> 命令的一些選項。</p><p>用下面的命令檢查在 team0 運行的端口。</p><pre><code># teamnl team0 ports
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/teamnl-check-ports.png" alt="teamnl 檢查端口"></p><p>顯示 <strong>team0</strong> 當前活動的端口。</p><pre><code># teamnl team0 getoption activeport
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/display-active-port-team0.png" alt="顯示 team0 活動端口"></p><p>好了，我們已經成功地配置了網卡綁定 😃 ，如果有任何反饋，請告訴我們。</p><hr>`,61)),a("p",null,[n[1]||(n[1]=t("via: ",-1)),o(e,{href:"http://linoxide.com/linux-command/interface-nics-bonding-linux/"},{default:p(()=>[...n[0]||(n[0]=[t("http://linoxide.com/linux-command/interface-nics-bonding-linux/",-1)])]),_:1})]),a("p",null,[n[5]||(n[5]=t("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...n[2]||(n[2]=[t("Arun Pyasi",-1)])]),_:1}),n[6]||(n[6]=t(" 譯者：",-1)),o(e,{href:"https://github.com/ictlyh"},{default:p(()=>[...n[3]||(n[3]=[t("ictlyh",-1)])]),_:1}),n[7]||(n[7]=t(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:p(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),a("p",null,[n[10]||(n[10]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:p(()=>[...n[9]||(n[9]=[t("Linux中國",-1)])]),_:1}),n[12]||(n[12]=t(" 榮譽推出",-1))])])}const C=i(m,[["render",d]]);export{T as __pageData,C as default};
